import { Mesh, PlaneGeometry, Object3D, Euler } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // --- Load texture (synchronously via cached loader) ---
  const texture = ctx.textureLoader(config.assets?.imageUrl ?? '');

  // --- Determine plane size based on atlas region aspect ratio ---
  // Fallback to a 1 × 1 size if region data is missing.
  const atlasRect = config.atlasRegion ?? { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlasRect.width / atlasRect.height || 1;
  const planeWidth = aspect;
  const planeHeight = 1;

  // --- Create geometry and material ---
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ map: texture, side: 2 /* DoubleSide */ });

  // Apply UV offset / repeat for atlas region if known.
  if (texture && atlasRect && typeof ctx.atlasSize === 'object') {
    const atlasW = ctx.atlasSize.width || 1;
    const atlasH = ctx.atlasSize.height || 1;
    texture.offset.set(atlasRect.x / atlasW, atlasRect.y / atlasH);
    texture.repeat.set(atlasRect.width / atlasW, atlasRect.height / atlasH);
    texture.needsUpdate = true;
  }

  const mesh = new Mesh(geometry, material);

  // --- Placement ---
  const pos = config.position ?? [0, 0, 0];
  mesh.position.set(pos[0], pos[1], pos[2]);

  const rot = config.rotation ?? [0, 0, 0];
  mesh.rotation.set(rot[0], rot[1], rot[2]);

  const scl = config.scale ?? [1, 1, 1];
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // --- Billboard toward camera (onBeforeRender) ---
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // --- User data for event handlers and cleanup ---
  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    // Stop any GSAP timelines that might have been started elsewhere.
    gsap.globalTimeline.clear();

    geometry.dispose();
    material.dispose();
    if (texture) {
      texture.dispose();
    }
    mesh.onBeforeRender = null;
  };

  return mesh;
}
